import json,sys,base64,re
from email.utils import parsedate_to_datetime
def dec(d):
    try: return base64.urlsafe_b64decode(d+'==').decode('utf-8','replace')
    except Exception as e: return '<decode err>'
def body(p):
    out=[]
    mt=p.get('mimeType','')
    if mt=='text/plain' and p.get('body',{}).get('data'): out.append(dec(p['body']['data']))
    for c in p.get('parts',[]) or []: out+=body(c)
    if not out and mt=='text/html' and p.get('body',{}).get('data'):
        out.append(re.sub('<[^>]+>',' ',dec(p['body']['data'])))
    return out
def trim(t):
    m=re.search(r'\n\s*On .{0,200}?wrote:',t,re.S)
